import numpy as np

def step(r,x,s):
    # QR Lanczos orthogonal poly
    vs=[r/np.linalg.norm(r)]
    for j in range(s):
      w=x*vs[-1]
      for v in vs: w-=np.dot(v,w)*v
      if np.linalg.norm(w)<1e-13: return None
      vs.append(w/np.linalg.norm(w))
    return vs[-1] # monic polynomial sign positive; even s same actual

